package cmd

import (
	"path/filepath"
	"strings"
	"testing"
)

func templFixture() map[string]string {
	return map[string]string{
		"go.mod": "module testmod\n\ngo 1.21\n",
		"main.go": `package main

func main() {
	_ = Header("hi")
}
`,
		"header_templ.go": `// Code generated by templ - DO NOT EDIT.

package main

func Header(title string) string { return title }
`,
		"header.templ": `package main

templ Header(title string) {
	<h1>{ title }</h1>
}
`,
	}
}

func TestTemplSourceMapping(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"header.templ": "templ Header() {\n\t<h1>hi</h1>\n}\n",
	})

	got, ok := templSource(filepath.Join(dir, "header_templ.go"))
	if !ok || got != filepath.Join(dir, "header.templ") {
		t.Fatalf("templSource = %q, %v; want header.templ", got, ok)
	}

	if _, ok := templSource(filepath.Join(dir, "missing_templ.go")); ok {
		t.Error("templSource should not match without a sibling .templ file")
	}
	if _, ok := templSource(filepath.Join(dir, "header.go")); ok {
		t.Error("templSource should not match a non-generated .go file")
	}

	if got := displayPath(filepath.Join(dir, "header_templ.go")); got !=
		filepath.Join(dir, "header.templ") {
		t.Errorf("displayPath = %q, want header.templ", got)
	}
}

func TestTemplSignature(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"a.templ": `package views

templ Header(title string, count int) {
	<h1>{ title }</h1>
}

templ Multi(
	title string,
	items []string,
) {
	<div></div>
}

templ Generic[T ~[]byte](items T) {
	<span></span>
}
`,
	})
	src := filepath.Join(dir, "a.templ")

	cases := []struct {
		name string
		want string
	}{
		{"Header", "templ Header(title string, count int)"},
		{"Multi", "templ Multi(\n\ttitle string,\n\titems []string,\n)"},
		{"Generic", "templ Generic[T ~[]byte](items T)"},
	}
	for _, c := range cases {
		got, ok := templSignature(src, c.name)
		if !ok {
			t.Fatalf("%s: signature not found", c.name)
		}
		if got != c.want {
			t.Errorf("%s: got %q, want %q", c.name, got, c.want)
		}
	}

	if _, ok := templSignature(src, "Missing"); ok {
		t.Error("expected no signature for an undeclared component")
	}
}

func TestTemplSignature_Malformed(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"a.templ": "package views\n\ntempl A[T any(\n\ntempl B\n\ntempl C(\n",
	})
	src := filepath.Join(dir, "a.templ")

	for _, name := range []string{"A", "B", "C"} {
		if _, ok := templSignature(src, name); ok {
			t.Errorf("%s: expected malformed declarations to be rejected", name)
		}
	}
	if _, ok := templSignature(filepath.Join(dir, "nope.templ"), "A"); ok {
		t.Error("expected an unreadable source to be rejected")
	}
}

func TestClosureItems_DeduplicatesDisplayPath(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"header.templ": "templ Header() {\n\t<h1>hi</h1>\n}\n",
	})
	gen := filepath.Join(dir, "header_templ.go")
	seen := map[string]bool{}

	items := closureItems([]string{gen, gen}, seen)
	if len(items) != 1 {
		t.Fatalf("items = %v, want a single entry", items)
	}
	want := filepath.Join(dir, "header.templ")
	if items[0].path != want {
		t.Errorf("item path = %q, want %q", items[0].path, want)
	}
	if !seen[gen] || !seen[want] {
		t.Errorf("seen = %v, want both generated and source paths", seen)
	}
}

func TestRootRun_TemplEntryPoint(t *testing.T) {
	dir := writeModule(t, templFixture())

	out, _ := resetRootCmd()
	rootCmd.SetArgs([]string{filepath.Join(dir, "header.templ")})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "Input file: header.templ") {
		t.Errorf("input header should show the .templ source:\n%s", got)
	}
	if !strings.Contains(got, "FILE: header.templ") ||
		!strings.Contains(got, "templ Header(title string)") {
		t.Errorf("output should contain the .templ source:\n%s", got)
	}
	if strings.Contains(got, "FILE: header_templ.go") {
		t.Errorf("generated Go file leaked into the output:\n%s", got)
	}
	if !strings.Contains(got, "Total files included: 1") {
		t.Errorf("expected exactly one file:\n%s", got)
	}
}

func TestRootRun_GoFilePullsInTemplSource(t *testing.T) {
	dir := writeModule(t, templFixture())

	out, _ := resetRootCmd()
	rootCmd.SetArgs([]string{filepath.Join(dir, "main.go")})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "FILE: header.templ") {
		t.Errorf("templ component should be reachable from main.go:\n%s", got)
	}
	if strings.Contains(got, "header_templ.go") {
		t.Errorf("generated Go file leaked into the output:\n%s", got)
	}
	if !strings.Contains(got, "Total files included: 2") {
		t.Errorf("expected main.go + header.templ:\n%s", got)
	}
}

func TestRootRun_TemplWithoutGeneratedFile(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"orphan.templ": "package main\n\ntempl Orphan() {\n\t<p>hi</p>\n}\n",
	})

	out, errOut := resetRootCmd()
	rootCmd.SetArgs([]string{filepath.Join(dir, "orphan.templ")})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "FILE: orphan.templ") {
		t.Errorf("orphan .templ should be included as-is:\n%s", got)
	}
	if !strings.Contains(errOut.String(), "has no generated") {
		t.Errorf("expected a warning on stderr, got: %q", errOut.String())
	}
}

func TestRootRun_TemplAndGeneratedTogether(t *testing.T) {
	dir := writeModule(t, templFixture())

	out, _ := resetRootCmd()
	rootCmd.SetArgs([]string{
		filepath.Join(dir, "header.templ"),
		filepath.Join(dir, "header_templ.go"),
	})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if strings.Count(got, "FILE: header.templ") != 1 {
		t.Errorf("templ source should appear exactly once:\n%s", got)
	}
	if !strings.Contains(got, "Total files included: 1") {
		t.Errorf("both arguments denote the same file:\n%s", got)
	}
}

func TestRootRun_DepthFlag_TemplSignature(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"go.mod": "module testmod\n\ngo 1.21\n",
		"main.go": `package main

func main() {
	Footer("hi")
}
`,
		"footer_templ.go": `// Code generated by templ - DO NOT EDIT.

package main

func Footer(msg string) string { return msg }
`,
		"footer.templ": `package main

templ Footer(msg string) {
	<footer>{ msg }</footer>
}
`,
	})

	out, _ := resetRootCmd()
	rootCmd.SetArgs([]string{"--depth", "0", filepath.Join(dir, "main.go")})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "templ Footer(msg string)") {
		t.Errorf("expected the .templ signature:\n%s", got)
	}
	if !strings.Contains(got, "// from footer.templ") {
		t.Errorf("signature should be attributed to footer.templ:\n%s", got)
	}
	if strings.Contains(got, "func Footer(") {
		t.Errorf("Go boilerplate signature leaked into the output:\n%s", got)
	}
	if strings.Contains(got, "FILE: footer.templ") {
		t.Errorf("footer.templ is beyond the depth limit:\n%s", got)
	}
}

func TestRootRun_DepthFlag_TemplWithinLimit(t *testing.T) {
	dir := writeModule(t, map[string]string{
		"go.mod": "module testmod\n\ngo 1.21\n",
		"main.go": `package main

func main() {
	Footer("hi")
}
`,
		"footer_templ.go": `// Code generated by templ - DO NOT EDIT.

package main

func Footer(msg string) string { return msg }
`,
		"footer.templ": `package main

templ Footer(msg string) {
	<footer>{ msg }</footer>
}
`,
	})

	out, _ := resetRootCmd()
	rootCmd.SetArgs([]string{"--depth", "1", filepath.Join(dir, "main.go")})

	err := rootCmd.Execute()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	got := out.String()
	if !strings.Contains(got, "FILE: footer.templ") {
		t.Errorf("footer.templ should be included within the depth limit:\n%s",
			got)
	}
	if strings.Contains(got, "footer_templ.go") {
		t.Errorf("generated Go file leaked into the output:\n%s", got)
	}
}
